export default function hop({ initialUrl, previousState }) {
  const candidate = previousState?.nextUrl || initialUrl;
  let url;
  try {
    url = new URL(candidate);
  } catch {
    throw Error("Configure a valid HTTP or HTTPS target URL");
  }
  if (!["http:", "https:"].includes(url.protocol) || url.username || url.password)
    throw Error("Configure an HTTP or HTTPS URL without credentials");
  return { url: url.toString() };
}

