function validUrl(value) {
  if (
    typeof value !== "string" ||
    /[\s\x00-\x1f\x7f\\]/.test(value) ||
    /%(?![0-9a-f]{2})/i.test(value)
  )
    return false;
  const match = /^https?:\/\/([^/?#]+)(?:[/?#].*)?$/i.exec(value);
  if (!match || match[1].includes("@")) return false;
  const authority = match[1];
  let host, port;
  if (authority.startsWith("[")) {
    const parts = /^\[([0-9a-f:]+)\](?::(\d+))?$/i.exec(authority);
    if (!parts) return false;
    host = parts[1];
    port = parts[2];
    const halves = host.split("::");
    if (halves.length > 2) return false;
    const groups = halves.flatMap((part) => (part ? part.split(":") : []));
    if (groups.some((group) => !/^[0-9a-f]{1,4}$/i.test(group))) return false;
    if (halves.length === 1 ? groups.length !== 8 : groups.length >= 8) return false;
  } else {
    const parts = /^([^:]+)(?::(\d+))?$/.exec(authority);
    if (!parts) return false;
    host = parts[1];
    port = parts[2];
    if (host.length > 253) return false;
    const labels = host.replace(/\.$/, "").split(".");
    if (
      !labels.every(
        (label) =>
          label.length > 0 &&
          label.length <= 63 &&
          /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(label),
      )
    )
      return false;
    if (
      labels.every((label) => /^\d+$/.test(label)) &&
      (labels.length !== 4 || labels.some((label) => Number(label) > 255))
    )
      return false;
  }
  return port === undefined || (port.length <= 5 && Number(port) <= 65535);
}

export default function check({ url, statusCode, headers, body, previousState }) {
  const hops = previousState?.hops ?? 0;
  if (
    !Number.isInteger(statusCode) ||
    statusCode < 100 ||
    statusCode > 599 ||
    !Number.isInteger(hops) ||
    hops < 0
  )
    throw Error("Invalid response");
  if (
    statusCode >= 300 &&
    statusCode < 400 &&
    typeof headers?.location === "string" &&
    headers.location
  ) {
    if (hops >= 21) throw Error("Too many redirects");
    let target;
    try {
      target = new URL(headers.location, url);
    } catch {
      throw Error("Invalid redirect");
    }
    if (!["http:", "https:"].includes(target.protocol) || target.username || target.password)
      throw Error("Invalid redirect");
    return {
      state: { hops: hops + 1, nextUrl: target.toString() },
      redirect: true,
      photo: "https://example.invalid/redirect",
      caption: "",
    };
  }
  if (statusCode < 200 || statusCode >= 300) throw Error("Cocktail API request failed");
  let data;
  try {
    data = JSON.parse(body);
  } catch {
    throw Error("Invalid cocktail JSON");
  }
  const drink = data?.drinks?.[0];
  if (
    typeof drink?.strDrink !== "string" ||
    !drink.strDrink ||
    typeof drink.strDrinkThumb !== "string" ||
    !validUrl(drink.strDrinkThumb)
  )
    throw Error("Missing cocktail name or photo");
  if (drink.strDrink.length > 1024) throw Error("Cocktail caption exceeds Telegram limit");
  return {
    state: { hops, nextUrl: "" },
    redirect: false,
    photo: drink.strDrinkThumb,
    caption: drink.strDrink,
  };
}
